PRAGMA foreign_keys = ON;
CREATE TABLE Learner (learner_id TEXT PRIMARY KEY, learner_name TEXT NOT NULL, track_id TEXT NOT NULL, experience_level TEXT NOT NULL CHECK(experience_level IN ('Beginner','Intermediate','Advanced')), learner_status TEXT NOT NULL CHECK(learner_status IN ('Active','Inactive')));
CREATE TABLE Course (course_id TEXT PRIMARY KEY, course_name TEXT NOT NULL, course_status TEXT NOT NULL CHECK(course_status IN ('Active','Inactive')));
CREATE TABLE Skill (skill_id TEXT PRIMARY KEY, skill_name TEXT NOT NULL, domain TEXT NOT NULL, difficulty_level TEXT NOT NULL CHECK(difficulty_level IN ('Beginner','Intermediate','Advanced')));
CREATE TABLE SkillPrerequisite (prerequisite_id TEXT PRIMARY KEY, skill_id TEXT NOT NULL REFERENCES Skill(skill_id), prerequisite_skill_id TEXT NOT NULL REFERENCES Skill(skill_id), effective_from TEXT NOT NULL, effective_to TEXT, CHECK(skill_id <> prerequisite_skill_id), CHECK(effective_to IS NULL OR effective_to > effective_from), UNIQUE(skill_id,prerequisite_skill_id,effective_from,effective_to));
CREATE TABLE ContentItem (content_id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES Course(course_id), content_title TEXT NOT NULL, content_type TEXT NOT NULL CHECK(content_type IN ('Video','PDF','Quiz','Exercise','Project')), difficulty_level TEXT NOT NULL CHECK(difficulty_level IN ('Beginner','Intermediate','Advanced')), duration_minutes INTEGER NOT NULL CHECK(duration_minutes > 0), content_status TEXT NOT NULL CHECK(content_status IN ('Active','Inactive')));
CREATE TABLE ContentSkill (content_skill_id TEXT PRIMARY KEY, content_id TEXT NOT NULL REFERENCES ContentItem(content_id), skill_id TEXT NOT NULL REFERENCES Skill(skill_id), UNIQUE(content_id,skill_id));
CREATE TABLE Attempt (attempt_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), content_id TEXT NOT NULL REFERENCES ContentItem(content_id), attempted_at TEXT NOT NULL, score REAL NOT NULL CHECK(score BETWEEN 0 AND 1), attempt_number INTEGER NOT NULL CHECK(attempt_number > 0), attempt_kind TEXT NOT NULL CHECK(attempt_kind IN ('INITIAL','RETAKE')), UNIQUE(learner_id,attempt_number));
CREATE TABLE AssessmentResult (assessment_id TEXT PRIMARY KEY REFERENCES Attempt(attempt_id), score REAL NOT NULL CHECK(score BETWEEN 0 AND 1), assessment_type TEXT NOT NULL);
CREATE TABLE Recommendation (recommendation_id TEXT PRIMARY KEY, snapshot_id TEXT NOT NULL, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), content_id TEXT NOT NULL REFERENCES ContentItem(content_id), skill_id TEXT NOT NULL REFERENCES Skill(skill_id), mapped_skill_ids TEXT NOT NULL, recommended_at TEXT NOT NULL, rank INTEGER NOT NULL CHECK(rank > 0), reason_code TEXT NOT NULL, mastery_at_recommendation REAL NOT NULL CHECK(mastery_at_recommendation BETWEEN 0 AND 1), difficulty_target TEXT NOT NULL, difficulty_selected TEXT NOT NULL, difficulty_fallback INTEGER NOT NULL CHECK(difficulty_fallback IN (0,1)), evidence_attempt_ids TEXT NOT NULL, evidence_assessment_ids TEXT NOT NULL, explanation_json TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE BaselinePolicyRecommendation (recommendation_id TEXT PRIMARY KEY, snapshot_id TEXT NOT NULL, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), content_id TEXT NOT NULL REFERENCES ContentItem(content_id), skill_id TEXT NOT NULL REFERENCES Skill(skill_id), mapped_skill_ids TEXT NOT NULL, recommended_at TEXT NOT NULL, rank INTEGER NOT NULL CHECK(rank > 0), reason_code TEXT NOT NULL, mastery_at_recommendation REAL NOT NULL CHECK(mastery_at_recommendation BETWEEN 0 AND 1), difficulty_target TEXT NOT NULL, difficulty_selected TEXT NOT NULL, difficulty_fallback INTEGER NOT NULL CHECK(difficulty_fallback IN (0,1)), evidence_attempt_ids TEXT NOT NULL, evidence_assessment_ids TEXT NOT NULL, explanation_json TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE LearningPath (learning_path_id TEXT NOT NULL, snapshot_id TEXT NOT NULL, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), sequence_no INTEGER NOT NULL CHECK(sequence_no > 0), recommendation_id TEXT NOT NULL REFERENCES Recommendation(recommendation_id), content_id TEXT NOT NULL REFERENCES ContentItem(content_id), created_at TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY(learning_path_id,sequence_no));
CREATE TABLE LearnerDecision (snapshot_id TEXT NOT NULL, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), decision_at TEXT, decision_code TEXT NOT NULL, eligible_skill_count INTEGER NOT NULL CHECK(eligible_skill_count >= 0), candidate_content_count INTEGER NOT NULL CHECK(candidate_content_count >= 0), reason_detail TEXT NOT NULL, PRIMARY KEY(snapshot_id,learner_id));
CREATE TABLE DomainEvent (event_id TEXT PRIMARY KEY, snapshot_id TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, event_at TEXT, old_state TEXT NOT NULL, new_state TEXT NOT NULL, reason_code TEXT NOT NULL, evidence_json TEXT NOT NULL);
CREATE TABLE RecommendationOutcome (recommendation_id TEXT PRIMARY KEY REFERENCES Recommendation(recommendation_id), snapshot_id TEXT NOT NULL, learner_id TEXT NOT NULL REFERENCES Learner(learner_id), skill_id TEXT NOT NULL REFERENCES Skill(skill_id), ground_truth_label TEXT NOT NULL CHECK(ground_truth_label IN ('COMPLETED_SUCCESS','FOLLOWUP_BELOW_THRESHOLD','NO_FOLLOWUP')), followup_attempt_id TEXT REFERENCES Attempt(attempt_id), followup_assessment_id TEXT REFERENCES AssessmentResult(assessment_id), followup_at TEXT, followup_score REAL CHECK(followup_score IS NULL OR followup_score BETWEEN 0 AND 1), observation_window_start TEXT NOT NULL, observation_window_end TEXT, outcome_scope TEXT NOT NULL, issue_type TEXT NOT NULL);
CREATE INDEX ix_attempt_learner_time ON Attempt(learner_id,attempted_at);
CREATE INDEX ix_content_skill_skill ON ContentSkill(skill_id,content_id);
CREATE INDEX ix_recommendation_learner_time ON Recommendation(learner_id,recommended_at);
